      es: ["Número de empresas MEM: más de 100", "Empleados en la industria: cerca de 15.000", "Fundación Sulzer: 1834", "Altitud de la ciudad: 450 m s. n. m.", "Estudiantes de ZHAW: más de 12.000", "Cuota de exportación: más del 50 %"],
      pt: ["Número de empresas MEM: mais de 100", "Empregados na indústria: cerca de 15.000", "Fundação Sulzer: 1834", "Altitude da cidade: 450 m a.n.m.", "Estudantes da ZHAW: mais de 12.000", "Quota de exportação: mais de 50%"],
      fr: ["Nombre d'entreprises MEM : plus de 100", "Employés dans l'industrie : environ 15 000", "Fondation Sulzer : 1834", "Altitude de la ville : 450 m", "Étudiants à la ZHAW : plus de 12 000", "Taux d'exportation : plus de 50 %"],
