      es: ["Base de empresas medianas", "Proximidad a la región económica de Zúrich", "Fuerte economía local", "Artesanía tradicional"],
      pt: ["Base de empresas médias", "Proximidade à região económica de Zurique", "Forte economia local", "Artesanato tradicional"],
