      es: ["Proveedores para marcas de primer nivel", "Alta precisión de fabricación", "Proximidad tecnológica a Lausana", "Proveedor importante"],
      pt: ["Fornecedores para marcas de topo", "Alta precisão de fabricação", "Proximidade tecnológica a Lausanne", "Fornecedor importante"],
